C++JavaPython <pre><code>int dijkstra(const vector&lt;vector&lt;pair&lt;int, int&gt;&gt;&gt;&amp; graph, int src) {
  vector&lt;int&gt; dist(graph.size(), INT_MAX);

  dist[src] = 0;
  using P = pair&lt;int, int&gt;;  // (d, u)
  priority_queue&lt;P, vector&lt;P&gt;, greater&lt;&gt;&gt; minHeap;
  minHeap.emplace(dist[src], src);

  while (!minHeap.empty()) {
    const auto [d, u] = minHeap.top();
    minHeap.pop();
    if (d &gt; dist[u])
      continue;
    for (const auto&amp; [v, w] : graph[u])
      if (d + w &lt; dist[v]) {
        dist[v] = d + w;
        minHeap.emplace(dist[v], v);
      }
  }

  const int maxDist = ranges::max(dist);
  return maxDist == INT_MAX ? -1 : maxDist;
}
</code></pre> <pre><code>private int dijkstra(List&lt;Pair&lt;Integer, Integer&gt;&gt;[] graph, int src) {
  int[] dist = new int[graph.length];
  Arrays.fill(dist, Integer.MAX_VALUE);

  dist[src] = 0;
  Queue&lt;Pair&lt;Integer, Integer&gt;&gt; minHeap =
    new PriorityQueue&lt;&gt;(Comparator.comparing(Pair::getKey)) {
      { offer(new Pair&lt;&gt;(dist[src], src)); } // (d, u)
    };

  while (!minHeap.isEmpty()) {
    final int d = minHeap.peek().getKey();
    final int u = minHeap.poll().getValue();
    if (d &gt; dist[u])
      continue;
    for (Pair&lt;Integer, Integer&gt; pair : graph[u]) {
      final int v = pair.getKey();
      final int w = pair.getValue();
      if (d + w &lt; dist[v]) {
        dist[v] = d + w;
        minHeap.offer(new Pair&lt;&gt;(dist[v], v));
      }
    }
  }

  final int maxDist = Arrays.stream(dist).max().getAsInt();
  return maxDist == Integer.MAX_VALUE ? -1 : maxDist;
}
