  rowsCount: number,
  colsCount: number
): number[][] {
  if (rowsCount * colsCount != this.length) {
    return [];
  }
  const ans: number[][] = [];
  for (let i = 0; i &lt; rowsCount; ++i) {
    ans.push([]);
  }
  for (let i = 0; i &lt; rowsCount; ++i)
    for (let j = 0; j &lt; colsCount; ++j) {
      const k = j * rowsCount + (j % 2 == 0 ? i : rowsCount - 1 - i);
