TypeScript <pre><code>function* factorial(n: number): Generator&lt;number&gt; {
  if (n === 0) {
    yield 1;
  }
  let fact = 1;
  for (let i = 1; i &lt;= n; ++i) {
    fact *= i;
    yield fact;
  }
}
